            </div>
            <p className="mt-4 text-[13px] leading-relaxed text-ink-500">
              Nominal und vor Steuern – eine Orientierung, kein Angebot. Das konkrete Pachtangebot hängt von Netzanschluss, Kulisse und Baurecht ab.
            </p>
          </div>
        </>
      }
    />
  );
}

