cd ~/claude-browser && cat > rech-dbg.mjs <<'EOF'
import { chromium } from "playwright";
const browser = await chromium.launch();
const page = await (await browser.newContext({ viewport: { width: 1440, height: 900 } })).newPage();
await page.addInitScript(() => { try { localStorage.setItem("cookie-consent", "necessary"); } catch {} });
await page.goto(process.argv[2], { waitUntil: "load", timeout: 180000 });
await page.waitForTimeout(1500);
const karte = page.locator("[data-ergebnis-anfrage]").first();
await karte.scrollIntoViewIfNeeded();
await page.evaluate(() => { const s = document.querySelector("[data-ergebnis-anfrage] > span"); const orig = s.animate.bind(s); window.__anim = 0; s.animate = (...a) => { window.__anim++; return orig(...a); }; });
const range = page.locator('input[type="range"]').nth(1);
await range.focus();
for (let i = 0; i < 6; i++) { await page.keyboard.press("ArrowRight"); await page.waitForTimeout(60); }
await page.waitForTimeout(1500);
console.log(await page.evaluate(() => ({ anim: window.__anim, rect: JSON.stringify(document.querySelector("[data-ergebnis-anfrage]").getBoundingClientRect()), h: innerHeight })));
await browser.close();
EOF
